_ROOT = _os.path.normpath(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '..', '..', '..'))   # THE PORTABLE REPO (2026-09-15): the repo root from this file's own place
#!/usr/bin/env python3
# THE DEUTERONOMY WALK 17b (LEAN): the commit message built from the prints — sittings 15, 15b, 16, 16b, 17 (chapters 17-25 read and compiled through 21, 22-25 read) and 17b
