import os, re, subprocess, ast, glob
ROOT = _ROOT
SP = os.path.dirname(os.path.abspath(__file__))
def rd(p): return open(p, encoding='utf-8').read()
def R(pat, text, name):
    g = re.search(pat, text, re.M); assert g, (name, pat); return g.group(1)
def RL(pat, text, name):
    g = re.findall(pat, text, re.M); assert g, (name, pat); return g[-1]
TRAIL = 'Co-Authored-By: Claude Fable 5.1 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01MiJCE3AxFHu3jksQa2GG21\n'
def strip_trailers(m):
    m = m.replace(TRAIL, '').rstrip('\n')
    assert 'Co-Authored-By' not in m and 'Claude-Session' not in m, 'the trailers stripped'
    return m
summ = rd(f'{SP}/ch22b_gates_SUMMARY.txt'); assert 'ALL GREEN' in summ, 'the chain not green — the tail files its demands first'
STEPS = re.findall(r'^(PASS|FAIL|SKIP) (\w+)(?: rc=\d+)? \((\d+)s\)', summ, re.M); CHAIN_S = sum(int(t) for _, _, t in STEPS)
SWEEP = R(r'(\d+/\d+) runners green', rd(f'{SP}/ch22b_gates/sweep.out'), 'the sweep')
runs = sorted(glob.glob(f'{SP}/ch22_runner_run*.out')); run = rd(runs[-1]); MATRIX = RL(r'^MATRIX: (\d+/\d+) cells', run, 'the runner'); W = ast.literal_eval(R(r'^THE NARRATIVE: (\(\d+, \d+, \d+, \(\d+, \d+\), \d+, \d+, \d+, \d+\))', run, 'the narrative'))[0]
NPAR = int(R(r'the parameters (\d+) \(in the registry 0, in DATA \d+\)', run, 'the parameters')); NDATA = int(R(r'; DATA rows (\d+)$', run, 'data')); RBG = R(r'^THE READBACK — THE FORMS ON FILE, NO NEW FORM: 96 rows — (\{[^}]+\});', run, 'the readback')
tapes = sorted(glob.glob(f'{SP}/ch22_tape_run*.out')); NRUN = len(tapes); TAPE_CP = R(r'^(\d+/10) checkpoints$', rd(tapes[-1]), 'the tape'); assert TAPE_CP == '10/10'
seq = rd(f'{ROOT}/World/step9/cold_run_sequence.py'); RUN = R(r"^RUN = \((\d+, \d+, \d+, \d+, \d+, \d+, \d+, \d+),", seq, 'RUN')
CASES = int(R(r'^CASES generated: (\d+)', rd(f'{SP}/ch22_cases_gen.out'), 'the cases'))
dep = rd(sorted(glob.glob(f'{SP}/ch22b_dependency_after*.out'))[-1]); NDEP = R(r'dispositions on file: (\d+ edges, \d+ pointers)', dep, 'the dispositions')
import yaml; MINE = len([e for e in yaml.safe_load(open(f'{ROOT}/World/step9/dependency_dispositions.yaml', encoding='utf-8'))['edges'] if e.get('from') == 'persons_poor_court'])
tim = [l.split('\t') for l in rd(f'{SP}/ch22b_timing.tsv').strip().split('\n') if l.split('\t')[1].startswith('17b')]; MACHINE_S = sum(int(t[2]) for t in tim)
PROBES = re.findall(r'^  (\w+): (\d+/\d+)$', rd(f'{SP}/ch22b_gates/probes.out'), re.M)
_reg = rd(f'{SP}/ch22b_gates/register.out'); REG = (re.search(r'(DECLARED \d+[^\n]*)', _reg, re.M) or re.search(r'(THE REGISTER GATE: GREEN)', _reg)).group(1)
NROWS = len(re.findall(r'^- Mishnah [A-Za-z ]+ \d+:\d+ — LAW\.', rd(f'{ROOT}/logic/oral_triage/deu_22_25_ki_teitzei_exam_2026-09-26.md'), re.M))
ta, tb = rd(f'{SP}/ch22_types_a.out'), rd(f'{SP}/ch22_types_b.out'); KADD, EADD = R(r'^kinds: (\d+) added of', ta, 'kinds'), R(r'^effects: (\d+) added', ta, 'effects'); DAEM = R(r'daemons (\d+), functions blocks', tb, 'daemons')
NFACT = len(re.findall(r'^FACT ', ''.join(rd(f'{SP}/ch22_callees{s}.out') for s in ('', '2', '3')), re.M)); NFAIL = len(re.findall(r'^FAIL ', ''.join(rd(f'{SP}/ch22_callees{s}.out') for s in ('', '2', '3')), re.M))
Q46 = R(r'readback_probes: (\d+/\d+)', rd(f'{SP}/ch22_probes_fail.out'), 'the probe')
m22 = strip_trailers(rd(f'{SP}/commit_msg_ch22.txt'))
HEAD = '''CHAPTERS 22-25 COMPILED IN THE LEAN FORM (SITTING 17b — THE LEAN PASS'S EIGHTH SITTING AND ITS FOURTH COMPILE, THE FIRST OVER FOUR CHAPTERS: ONE RUNNER AND ONE DAEMON OVER FOUR UNITS, TWENTY OWN-DAY LINES, THE FORTY-FOUR MISHNAH ROWS THE LEDGER CITES AT LEAST TWICE AS THE CASES, NO DOCKET, THE CHAIN ONCE AND GREEN ON ITS FIRST PASS — THE FULL PROCESS OWED) — THE LOST THING RETURNED AND NEVER HIDDEN FROM, THE MOTHER SENT FROM THE NEST, THE PARAPET WITH THE BLOODGUILT ON THE HOUSE, THE MIXTURES AND THE TASSELS, THE SLANDERED BRIDE WITH THE PLOTTING WITNESSES BY CALL AND THE GIRL WRITTEN AS A BOY AT HER TWELVE SEATS, THE ADULTERERS STRANGLED, THE BETROTHED IN THE CITY AND IN THE FIELD, THE SEDUCER'S FIFTY, THE ASSEMBLY'S BARS WITH AMMON AND MOAB FOREVER AND EDOM AND EGYPT AT THE THIRD, THE NIGHT'S CHANCE AND THE SPADE ON THE WEAPON, THE ESCAPED SLAVE NOT RETURNED, THE HARLOT'S HIRE AND THE DOG'S PRICE, THE INTEREST NOT BITTEN FROM A BROTHER, THE VOW NOT DELAYED PAST THREE FESTIVALS AND REFRAINING PERMITTED, THE LABORER'S HAND AND NEVER HIS VESSEL, THE DIVORCE'S WRIT WITH THE THREE ARMS OF 'SOME UNSEEMLY THING', THE NEWLYWED'S YEAR, THE MILLSTONE AS A LIFE, MIRIAM REMEMBERED, THE PLEDGE RETURNED BY SUNSET AND THE WAGE BEFORE THE SUN, FATHERS NOT FOR SONS, THE FORGOTTEN SHEAF AND THE GLEANINGS, THE FORTY LASHES LESS ONE, THE MUZZLE, THE LEVIRATE WITH THE SHOE LOOSED IN THE HOLY TONGUE AND THE HOUSE OF THE UNSHOD NAMED, THE WRESTLERS' WIFE'S HAND AS MONEY, THE WEIGHTS WHOLE AND JUST, AND AMALEK REMEMBERED, BLOTTED AND NEVER FORGOTTEN; AND BENEATH IT SITTINGS 15, 15b, 16, 16b AND 17 (CHAPTERS 17-21 READ AND COMPILED, CHAPTERS 22-25 READ) — ALL UNCOMMITTED SINCE f730559.

On the owner's words "Go" (RUN A, on sitting 17's tail with no compaction between — the run opened at 281k), "Reread and Go" (RUN B, after the compaction at #221) and "Go" (the tail, in RUN B's window after the chain's notification), 2026-09-26; World/step9/DEUTERONOMY_WALK.md "Sitting 17b — THE COMPILE OF CHAPTERS 22-25 … LEAN" (the design and the AS BUILT); the state doc's #221, #222 and its tail NOTE. RUN A: the recon over four chapters, the forty-four Mishnah rows COMPUTED from the reading's ledger (cited at least twice; 111 distinct citations) and read whole, the design (lint 0), the callees' facts from thirty-eight runners in three passes (%d facts, %d fails read — the keys from the sources, the facts by repr), the probe Q46 to FAIL (%s), the lean exam file (%d rows, lint 0); THE TYPES DEFERRED TO RUN B. RUN B: the types (%s kinds, %s effects — 34 blocks, 44 statuses, 1 heaven; the daemon law_persons_poor_court the %sth over four chapters with seventeen WRAPPED; the span four ranges; the OWED edge family -> deut_family PAID REVERSE; I5 79); the tape tools and the shells derived from 16b's forms; cold_run_persons_poor_court.py the 74th runner in seven typed parts and a generated eighth (part 1 derived — the helpers from the chapter 19-21 runner, the ink asserts from the reading's own instrument, the callees' facts in their own module read from the prints; parts 2-5 the sixteen cells; part 6 the readback's ninety-six rows, %d parameters and %d DATA rows; part 7 the daemon, the twenty lines as literal submits, the narrative); %d cases generated from the cells' own asks; %s on the first graded run and the second (%d writes on Israel, every one its first entry; the readback %s); the gates alone — the daemon gate green on literal submits, the dependency gate's demands filed in four sets from its prints (three pointers; three PARAMETER carries value for the DATA reads; four FALSE edges on consonantal homographs — the Sabbath's "turn back", the burnt offering's "her husband", the eldest "firstborn", the rain in "refraining"; the registration edge) — %d edges from the runner, %s on file; the tape %s on run %d (RUN (%s, the four pairs, 127); DK1-DK5 the D series' eleventh name; CU7's seven garment names and the rain's homograph widened at their sources from the scan census's print); THE GATES CHAIN ONE PASS ALL GREEN in %d s over %d steps (the probes %s; the register gate --strict %s; the positions at four workers; the sweep %s); %d timed steps, %d machine seconds. THE LESSONS (in the AS BUILT): a count assert in a filing script goes stale when a later set adds an edge; the census's homographs are consonantal; a scan's declared list is read from its source; a detached job gives no notification; the daemon gate reads literal submits only; the kin counts are one run's source; four chapters are one runner in seven parts plus the generated cases; the two-run rule held over four chapters. THE DEBT (COMPILE_DEBT's lean-pass box, line (7)): the docket whole, the pointer rows for 24:16, 25:19 and 25:9, the laborer's eating and the tassels' and the vineyard's parameters, the readback's exercises on Ruth's and Samuel's tapes, the persons and the court scene, the glosses, the ten deferred records.

''' % (NFACT, NFAIL, Q46, NROWS, KADD, EADD, DAEM, NPAR, NDATA, CASES, MATRIX, W, RBG, MINE, NDEP, TAPE_CP, NRUN, RUN, CHAIN_S, len(STEPS), PROBES, REG[:60], SWEEP, len(tim), MACHINE_S)
MSG = HEAD + '---- SITTING 17 (CHAPTERS 22-25 READ AND FROZEN, LEAN) AND BENEATH IT SITTINGS 15, 15b, 16 AND 16b — their own message as written at sitting 17\'s close ----\n\n' + m22 + '\n\n' + TRAIL
assert not re.search(r'[֐-׿]', HEAD) and MSG.endswith(TRAIL) and MSG.count('Co-Authored-By') == 1 and os.path.expanduser('~') not in MSG and SP not in MSG
open(f'{SP}/commit_msg_ch22b.txt', 'w', encoding='utf-8').write(MSG)
print('commit_msg_ch22b.txt %d bytes (17b head %d; 15-17 folded %d)' % (len(MSG.encode()), len(HEAD.encode()), len(m22.encode())))
